import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.TimeUnit;

public class ConcurrencyService {
    // Non-fair by default for optimal throughput
    private final Lock lock = new ReentrantLock(false);

    public void performCriticalWork() throws InterruptedException {
        // Interrupt-responsive acquisition
        lock.lockInterruptibly();
        try {
            // Safe execution zone
        } finally {
            lock.unlock();
        }
    }

    public boolean executeWithTryLock() {
        // Non-blocking conditional acquisition attempt
        if (lock.tryLock()) {
            try {
                // Acquired immediately
                return true;
            } finally {
                lock.unlock();
            }
        }
        // Lock was held by another thread; fallback logic here
        return false;
    }
}
